-- Migration 0008: 4-Tier Exam Taxonomy, Candidate Controls, Audit Logs & Preferences
-- Safe & idempotent for both local D1 and remote production D1 (cso-database).

CREATE TABLE IF NOT EXISTS exam_taxonomy (
  id TEXT PRIMARY KEY,
  domain_slug TEXT NOT NULL,
  domain_label TEXT NOT NULL,
  track_slug TEXT NOT NULL,
  track_label TEXT NOT NULL,
  exam_label TEXT NOT NULL,
  short_code TEXT NOT NULL,
  streams_json TEXT NOT NULL DEFAULT '[]',
  parent_tags TEXT NOT NULL DEFAULT '[]',
  next_exam_date TEXT,
  countdown_status TEXT NOT NULL DEFAULT 'TENTATIVE',
  marking_scheme_json TEXT NOT NULL DEFAULT '{"correct":1,"negative":0.25,"totalMarks":100}',
  syllabus_json TEXT NOT NULL DEFAULT '[]',
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_exam_taxonomy_domain ON exam_taxonomy(domain_slug, sort_order);
CREATE INDEX IF NOT EXISTS idx_exam_taxonomy_active ON exam_taxonomy(is_active, sort_order);

CREATE TABLE IF NOT EXISTS candidate_controls (
  user_id TEXT PRIMARY KEY,
  account_status TEXT NOT NULL DEFAULT 'active',
  restriction_reason TEXT,
  suspended_until TEXT,
  permissions_json TEXT NOT NULL DEFAULT '{"canTakeCbt":true,"canEditProfile":true,"canSyncCloud":true,"canBookmark":true,"canExportData":true}',
  assigned_exams_json TEXT NOT NULL DEFAULT '[]',
  lock_exam_preferences INTEGER NOT NULL DEFAULT 0,
  admin_notice_text TEXT,
  admin_notice_level TEXT NOT NULL DEFAULT 'info',
  session_version INTEGER NOT NULL DEFAULT 1,
  updated_by TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS candidate_audit_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL,
  action TEXT NOT NULL,
  actor TEXT NOT NULL,
  details TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_candidate_audit_user ON candidate_audit_logs(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS candidate_exam_preferences (
  user_id TEXT PRIMARY KEY,
  domain_slug TEXT,
  track_slug TEXT,
  primary_exam TEXT,
  selected_exams_json TEXT NOT NULL DEFAULT '[]',
  selected_streams_json TEXT NOT NULL DEFAULT '{}',
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

